package com.example.notify;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.env.Environment;
import org.springframework.stereotype.Service;

@Service
public class NotificationService {
    private static final Logger log = LoggerFactory.getLogger(NotificationService.class);

    private final Environment env;
    private final SmtpClient smtp;

    public NotificationService(Environment env, SmtpClient smtp) {
        this.env = env;
        this.smtp = smtp;
    }

    public void notifyShipped(Order order) {
        String appEnv = env.getProperty("app.env", "local");
        String baseUrl;
        if (appEnv.equals("prod")) {
            baseUrl = "https://shop.example.com";
        } else if (appEnv.equals("staging")) {
            baseUrl = "https://staging.shop.example.com";
        } else {
            baseUrl = "http://localhost:8080";
        }
        String link = baseUrl + "/orders/" + order.id();
        if (appEnv.equals("prod")) {
            smtp.send(order.email(), "Your order has shipped", link);
        } else {
            log.info("mail to {}: {}", order.email(), link);
        }
    }
}

