package com.example.notify;

public interface Mailer {
    void send(String to, String subject, String body);
}

package com.example.notify;

import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Component;

@Component
@Profile("prod")
public class SmtpMailer implements Mailer {
    private final SmtpClient smtp;

    public SmtpMailer(SmtpClient smtp) {
        this.smtp = smtp;
    }

    @Override
    public void send(String to, String subject, String body) {
        smtp.send(to, subject, body);
    }
}

package com.example.notify;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Component;

@Component
@Profile("!prod")
public class LoggingMailer implements Mailer {
    private static final Logger log = LoggerFactory.getLogger(LoggingMailer.class);

    @Override
    public void send(String to, String subject, String body) {
        log.info("mail to {} [{}]: {}", to, subject, body);
    }
}

@Service
public class NotificationService {
    private final Mailer mailer;
    private final String baseUrl;

    public NotificationService(Mailer mailer, @Value("${app.base-url}") String baseUrl) {
        this.mailer = mailer;
        this.baseUrl = baseUrl;
    }

    public void notifyShipped(Order order) {
        String link = baseUrl + "/orders/" + order.id();
        mailer.send(order.email(), "Your order has shipped", link);
    }
}
